      SUBROUTINE RDSTRG (STRING, LMAX, L)CC     READ A CHARACTER STRINGC      CHARACTER*1     STRING(LMAX)C---------------------------------------------------------------------      INCLUDE 'IODATA.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCHAR.CIN'CC     LOCAL VARIABLESC      CHARACTER*1     ISTOPC ---------------------------------------------------------------------C      DO 10 L = 1, LMAX   10 STRING(L) = BLANK      ITEM = KLINE(ICOL)      L = - 1      IF (ITEM .EQ. QUOTE .OR. ITEM .EQ. APOST .OR. ITEM .EQ. EQUAL     1 .OR. ITEM .EQ. SLASH .OR. ITEM .EQ. PARENO) GO TO 30      GO TO 100C   30 ISTOP = ITEM      IF (ITEM .EQ. PARENO) ISTOP = PARENC      L = 0   50 CALL RDFWRD      IF (ICOL .GT. 80) GO TO 60      IF (ITEM .EQ. ISTOP) GO TO 60      L = L + 1      STRING(L) = ITEM      GO TO 50   60 CONTINUEC  100 RETURN      END